const {chromium}=require('playwright'),fs=require('fs'),os=require('os'),path=require('path'),http=require('http'),assert=require('assert/strict'),{execFileSync}=require('child_process');
const repo=path.resolve(__dirname,'../..'),dir=fs.mkdtempSync(path.join(os.tmpdir(),'sambaadm-search-'));
execFileSync('go',['test','./internal/web','-run','^TestWorkspaceBrowserFixtures$','-count=1'],{cwd:repo,env:{...process.env,SAMBAADM_WEB_FIXTURE_DIR:dir}});
const server=http.createServer((req,res)=>{const p=new URL(req.url,'http://localhost').pathname,file=p.startsWith('/static/')?path.join(repo,'internal/web',p):path.join(dir,'admin-'+p.slice(1).replaceAll('/','_')+'.html');if(!fs.existsSync(file)){res.writeHead(404).end();return;}res.setHeader('Content-Type',file.endsWith('.js')?'application/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file));});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true});try{const page=await browser.newPage({viewport:{width:1280,height:900}}),errors=[],reads=[];page.on('pageerror',e=>errors.push(e.message));await page.route('**/api/v1/**',async route=>{const u=new URL(route.request().url()),path=u.pathname.slice(7);let json=[];if(path==='/share-servers')json={nodes:['dc1.example.com','dc2.example.com'],default:'dc1.example.com'};else if(path.startsWith('/shares')){const node=u.searchParams.get('node')||'dc1.example.com';reads.push([path,node]);const item={name:'docs',path:'/'+node+'/docs'};json=path==='/shares'?[item]:item;}await route.fulfill({json});});const base='http://127.0.0.1:'+server.address().port;await page.goto(base+'/shares');const select=page.getByLabel('Сервер общих папок',{exact:true});await select.selectOption('dc2.example.com');await page.getByRole('cell',{name:'/dc2.example.com/docs',exact:true}).waitFor();assert.equal(await page.getByRole('cell',{name:'/dc1.example.com/docs',exact:true}).count(),0);assert.equal(new URL(page.url()).searchParams.get('node'),'dc2.example.com');assert((await page.getByRole('link',{name:'Создать папку',exact:true}).getAttribute('href')).includes('node=dc2.example.com'));assert((await page.getByRole('link',{name:'Права и ACL',exact:true}).getAttribute('href')).includes('node=dc2.example.com'));await page.locator('tbody .row-actions summary').click();await page.getByRole('button',{name:'Свойства',exact:true}).click();const dialog=page.getByRole('dialog');await dialog.getByText('Сервер: dc2.example.com',{exact:true}).waitFor();await page.waitForFunction(()=>document.querySelector('.workspace-dialog').textContent.includes('/dc2.example.com/docs'));assert(reads.some(([path,node])=>path==='/shares/docs'&&node==='dc2.example.com'));await page.setViewportSize({width:390,height:844});assert.equal(await dialog.evaluate(e=>e.scrollWidth>e.clientWidth),false);assert.deepEqual(errors,[]);console.log('PASS selected server routes share list, properties, creation and ACL links; no stale rows; mobile');}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
